export type Colour = { name: string; hex: string };
export type Variant = { colour: string; size: string; stock: number };
export type Product = {
  id: string; slug: string; name: string; description: string; price: number; category: string;
  images: string[]; colours: Colour[]; sizes: string[]; variants: Variant[]; fabric: string; care: string;
  featured?: boolean; newArrival?: boolean; originalColor: string; colourMask?: string;
};

const stock = (colours: string[], sizes: string[], amount = 4): Variant[] =>
  colours.flatMap((colour) => sizes.map((size, i) => ({ colour, size, stock: Math.max(0, amount - ((i + colour.length) % 3)) })));

